import { useQuery } from '@tanstack/react-query';

function UserProfile({ userId }: { userId: string }) {
  const { data, isLoading, isFetching } = useQuery({
    queryKey: ['user', userId],
    queryFn: () => fetchUser(userId),
    staleTime: 1000 * 60 * 10, // 10 minutes â€” data stays fresh
    gcTime: 1000 * 60 * 60,   // 1 hour â€” cache kept after unmount
  });

  // isFetching is true during background refetches even when
  // data is available â€” useful for showing a subtle refresh indicator
  return (
    <div>
      {isFetching && !isLoading && <span className="refresh-badge">Updating...</span>}
      {data && <h1>{data.name}</h1>}
    </div>
  );
}

function UnstableResource() {
  const { data, error } = useQuery({
    queryKey: ['unstable-resource'],
    queryFn: fetchUnstableResource,
    retry: 2,              // Retry at most 2 times (3 total attempts)
    retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 5000),
    // Exponential backoff: 1s, 2s, 4s... capped at 5s
  });

  if (error) {
    return <p>Failed after retries: {error.message}</p>;
  }
  return <pre>{JSON.stringify(data, null, 2)}</pre>;
}

interface ApiResponse {
  users: User[];
  total: number;
  page: number;
}

function UserNames() {
  // select transforms the data â€” component only sees string[]
  const { data: userNames } = useQuery({
    queryKey: ['users'],
    queryFn: async () => {
      const res = await fetch('/api/users');
      return res.json() as Promise<ApiResponse>;
    },
    select: (response) => response.users.map(u => u.name),
  });

  // userNames is string[] here, not ApiResponse
  return (
    <ul>
      {userNames?.map((name, i) => (
        <li key={i}>{name}</li>
      ))}
    </ul>
  );
}
